<?php
/** نمای مراحل ۴ تا ۶؛ دادهٔ شرکت از سرویس و خروجی صرفاً escapeشده است. */
namespace Agah\Erp\Http;
use Agah\Erp\Core\{Db,Ctx,Request,Money,Jalali,Crypto,Audit,Settings,Business};
use Agah\Erp\Modules\Parties\PartyService;
use Agah\Erp\Modules\Catalog\CatalogService;
use Agah\Erp\Modules\Treasury\TreasuryService;
if(!defined('ABSPATH')) exit;
$to=Request::str('get','to',10);$to=$to?Jalali::parse($to):Jalali::today();$f=TreasuryService::forecast($cid,$to);$account=Request::int('get','account_id');$accounts=Db::rows('SELECT id,name FROM '.Db::t('treasury_accounts').' WHERE company_id=%d ORDER BY code',$cid);
?>
<section class="erp-card erp-print-document"><h2>گردش خزانه و پیش‌بینی نقدینگی</h2><form method="get" action="<?php echo esc_url(agah_erp_url()); ?>" class="erp-filter erp-no-print"><input type="hidden" name="page_id" value="<?php echo (int)get_option('agah_erp_page_id'); ?>"><input type="hidden" name="c" value="<?php echo (int)$cid; ?>"><input type="hidden" name="p" value="cash_forecast"><label>پیش‌بینی تا شمسی<input name="to" value="<?php echo esc_attr(Jalali::format($to,false)); ?>" data-jalali dir="ltr"></label><label>دفتر حساب<select name="account_id"><option value="0">جمع حساب‌ها</option><?php foreach($accounts as $a): ?><option value="<?php echo (int)$a['id']; ?>" <?php selected($account,$a['id']); ?>><?php echo esc_html($a['name']); ?></option><?php endforeach; ?></select></label><button type="submit" class="btn btn-outline">محاسبه</button></form>
<p>ماندهٔ فعلی همهٔ بانک/صندوق‌ها: <?php echo esc_html(Money::fmt($f['current'],Ctx::unit())); ?></p><p>پیش‌بینی بر مبنای سررسیدهای ثبت‌شده تا <?php echo esc_html(Jalali::format($to)); ?>: <?php echo esc_html(Money::fmt($f['expected'],Ctx::unit())); ?></p><p>پیش‌بینی، تضمین وصول نیست؛ فقط چک‌های در جریان و ماندهٔ فاکتورهای صادرشده را شامل می‌شود و اقلام معوق را نیز لحاظ می‌کند.</p>
<h3>چک‌های مؤثر</h3><?php foreach($f['cheques'] as $ch): ?><p><?php echo esc_html(($ch['direction']==='receipt'?'دریافت ':'پرداخت ').Jalali::format($ch['due_date']).' / '.Money::fmt((int)$ch['amount'],Ctx::unit())); ?></p><?php endforeach; ?>
<h3>فاکتورهای تسویه‌نشدهٔ مؤثر</h3><?php foreach($f['invoices'] as $inv): ?><p><?php echo esc_html($inv['kind'].' #'.$inv['id'].' / '.Jalali::format($inv['due_date']).' / '.Money::fmt((int)$inv['outstanding'],Ctx::unit())); ?></p><?php endforeach; ?>
<?php if($account):$l=TreasuryService::ledger($cid,$account,$to,Request::int('get','pg',1)); ?><h3><?php echo esc_html('دفتر '.$l['account']['name']); ?></h3><p>مانده: <?php echo esc_html(Money::fmt($l['balance'],Ctx::unit())); ?></p><div class="erp-scroll"><table class="erp-table"><thead><tr><th>تاریخ/سند</th><th>شرح</th><th>بدهکار</th><th>بستانکار</th></tr></thead><tbody><?php foreach($l['rows'] as $r): ?><tr><td><?php echo esc_html(Jalali::format($r['voucher_date']).' #'.Money::toFa($r['number'])); ?></td><td><?php echo esc_html($r['description']); ?></td><td><?php echo esc_html(Money::fmt((int)$r['debit'],Ctx::unit())); ?></td><td><?php echo esc_html(Money::fmt((int)$r['credit'],Ctx::unit())); ?></td></tr><?php endforeach; ?></tbody></table></div><?php self::pages($l['pages'],$l['page']);endif; ?><button type="button" class="btn btn-outline erp-no-print" data-print>چاپ گزارش</button></section>
